{"file_path":"src/election.js","content":"/**
 * Runs the instant-runoff count described for the CLI: each round tallies
 * every ballot for its most-preferred continuing candidate, a candidate
 * wins on a strict majority of the active total, and otherwise the
 * least-supported candidate is eliminated and another round is counted.
 */

/**
 * Picks which of the tied-for-fewest candidates to eliminate, given the
 * per-round tallies counted so far (including the current round). Compares
 * the tied group round by round from the first round, narrowing to
 * whichever had fewest votes at the first round the group's counts differ,
 * and falls back to the name that sorts last by code point when no round
 * ever separates them.
 */
function pickElimination(group, roundHistory) {
  let candidates = group.slice()
  for (const roundTally of roundHistory) {
    const values = candidates.map((c) => roundTally.get(c))
    const allEqual = values.every((v) => v === values[0])
    if (!allEqual) {
      const min = values.reduce((a, b) => (b < a ? b : a))
      candidates = candidates.filter((c) => roundTally.get(c) === min)
      if (candidates.length === 1) return candidates[0]
    }
  }
  candidates.sort()
  return candidates[candidates.length - 1]
}

/**
 * Runs the election to completion and returns `{ rounds, winner,
 * roundCount }`. Each entry of `rounds` is `{ tally, exhausted,
 * eliminated }`, where `tally` maps every candidate still continuing at
 * the start of that round to its vote count, and `eliminated` is the name
 * removed at the end of that round, or `null` for the final round.
 */
export function runElection({ candidates, ballots }) {
  const continuing = new Set(candidates)
  const rounds = []
  const roundHistory = []
  let winner = null

  while (true) {
    const tally = new Map()
    for (const c of continuing) tally.set(c, 0n)
    let exhausted = 0n

    for (const ballot of ballots) {
      const pick = ballot.candidates.find((c) => continuing.has(c))
      if (pick === undefined) exhausted += ballot.count
      else tally.set(pick, tally.get(pick) + ballot.count)
    }

    roundHistory.push(new Map(tally))

    let activeTotal = 0n
    for (const v of tally.values()) activeTotal += v

    let eliminated = null
    let done = false

    if (activeTotal === 0n) {
      done = true
    } else {
      let roundWinner = null
      for (const [name, votes] of tally) {
        if (votes * 2n > activeTotal) {
          roundWinner = name
          break
        }
      }
      if (roundWinner !== null) {
        winner = roundWinner
        done = true
      } else {
        let min = null
        for (const v of tally.values()) if (min === null || v < min) min = v
        const group = [...tally.entries()].filter(([, v]) => v === min).map(([n]) => n)
        eliminated = group.length === 1 ? group[0] : pickElimination(group, roundHistory)
        continuing.delete(eliminated)
      }
    }

    rounds.push({ tally, exhausted, eliminated })
    if (done) break
  }

  return { rounds, winner, roundCount: rounds.length }
}
"}

