{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js rounds` prints every round of the instant-runoff
 * count read from standard input, and `node src/cli.js tally` prints only how
 * many rounds ran and who won.
 */

import { parseElection, ParseError } from './parser.js'
import { runElection } from './election.js'

function formatRound(number, tally, exhausted) {
  const entries = [...tally.entries()]
  entries.sort(([nameA, votesA], [nameB, votesB]) => {
    if (votesA !== votesB) return votesA > votesB ? -1 : 1
    return nameA < nameB ? -1 : nameA > nameB ? 1 : 0
  })
  const parts = entries.map(([name, votes]) => `${name}=${votes}`)
  return `round ${number}: ${parts.join(' ')} exhausted=${exhausted}`
}

async function readStdin() {
  process.stdin.setEncoding('utf8')
  let input = ''
  for await (const chunk of process.stdin) input += chunk
  return input
}

async function main() {
